import React, { useState } from 'react';

const therapistIntro = `Hi, I'm your virtual therapist. I'm here to listen and support you. You can talk to me about how you're feeling, ask for advice, or just share what's on your mind. Remember, you're not alone, and reaching out is a brave step.`;

function getTherapistResponse(userMessage) {
  const msg = userMessage.toLowerCase();
  // More human, warm, and emoji-rich responses
  if (msg.includes('sad') || msg.includes('depressed')) {
    return (
      "I'm really sorry you're feeling this way. 💙 It's totally okay to feel sad sometimes. If you want to talk about it, I'm here to listen. Maybe we can find a little light together. 🌱"
    );
  }
  if (msg.includes('anxious') || msg.includes('anxiety') || msg.includes('nervous')) {
    return (
      "Anxiety can be so tough. 😟 Want to share what's on your mind, or maybe try a calming exercise with me? Remember, you're not alone in this. 🌊"
    );
  }
  if (msg.includes('alone') || msg.includes('lonely')) {
    return (
      "Feeling alone is really hard. 🤗 Please know you matter and I'm here for you. If you want, we can chat about ways to feel more connected or just hang out here for a bit. 💬"
    );
  }
  if (msg.includes('help')) {
    return (
      "Thank you for reaching out for help. That takes a lot of courage! 💪 Can you tell me a bit more about what's going on? I'm here to listen and support you however I can. 🫂"
    );
  }
  if (msg.includes('cope')) {
    return (
      "Coping looks different for everyone. 🌈 Some people like music, others write or go for a walk. Want to try a grounding exercise together, or talk about what helps you? 🌻"
    );
  }
  if (msg.includes('thank')) {
    return (
      "You're so welcome! 😊 Remember, you deserve kindness and support. If you ever want to chat, I'm just a message away. 💌"
    );
  }
  if (msg.includes('bye') || msg.includes('goodbye')) {
    return (
      "Take care of yourself! 🌟 Remember, you're never truly alone. Come back and chat anytime you need. Wishing you peace and good vibes! ✨"
    );
  }
  if (msg.includes('stress') || msg.includes('overwhelmed')) {
    return (
      "Sounds like things are a lot right now. 😣 Want to talk about what's stressing you out, or maybe try a quick breathing exercise together? Deep breaths can help! 🫁"
    );
  }
  if (msg.includes('angry') || msg.includes('mad')) {
    return (
      "Anger is a normal feeling, even if it doesn't always feel good. 😤 If you want, we can talk about what's making you upset, or I can share some ways to let that energy out safely. 💥"
    );
  }
  if (msg.includes('happy') || msg.includes('good')) {
    return (
      "Yay! I'm so glad to hear you're feeling good! 😃 Want to share what's making you smile today? I'm here to celebrate with you! 🎉"
    );
  }
  if (msg.includes('hi') || msg.includes('hello') || msg.includes('hey')) {
    return (
      "Hey there! 😊 It's great to hear from you. What's on your mind today?"
    );
  }
  // Default warm, human response
  return (
    "Thank you for sharing that with me. 💬 Your feelings matter, and I'm here to listen and support you. If you want to talk more or need some ideas for self-care, just let me know! 🌻"
  );
}

const VirtualTherapist = () => {
  const [messages, setMessages] = useState([
    { from: 'therapist', text: therapistIntro }
  ]);
  const [input, setInput] = useState('');

  const handleSend = (e) => {
    e.preventDefault();
    if (!input.trim()) return;
    const userMsg = { from: 'user', text: input };
    const therapistMsg = { from: 'therapist', text: getTherapistResponse(input) };
    setMessages([...messages, userMsg, therapistMsg]);
    setInput('');
  };

  return (
    <div className="card-area">
      <h3>Virtual Therapist <span role="img" aria-label="therapist">🧑‍⚕️</span></h3>
      <div className="therapist-chatbox">
        {messages.map((msg, idx) => (
          <div key={idx} className={`chat-msg ${msg.from}`}>{msg.text}</div>
        ))}
      </div>
      <form className="therapist-form" onSubmit={handleSend} autoComplete="off">
        <input
          type="text"
          value={input}
          onChange={e => setInput(e.target.value)}
          placeholder="Type your message... (I'm here for you)"
          maxLength={300}
        />
        <button type="submit">Send</button>
      </form>
    </div>
  );
};

