const MoodTracker = () => {
  const [todayMood, setTodayMood] = useState(null);
  const [history, setHistory] = useState([]);

  const handleMood = (mood) => {
    setTodayMood(mood);
    setHistory([mood, ...history.slice(0, 6)]); // Keep last 7 days
  };
  const handleReset = () => {
    setTodayMood(null);
  };

  return (
    <div className="card-area">
      <h3>How are you feeling today? <span role="img" aria-label="mood">🌈</span></h3>
      {!todayMood ? (
        <div className="mood-btn-row">
          {moods.map(m => (
            <button
              key={m.label}
              className="mood-btn"
              aria-label={m.label}
              onClick={() => handleMood(m)}
            >
              <span style={{fontSize: '2rem'}}>{m.emoji}</span>
              <span className="mood-label">{m.label}</span>
            </button>
          ))}
        </div>
      ) : (
        <div className="mood-selected">
          <p>Today you logged: <span style={{fontSize: '2rem'}}>{todayMood.emoji}</span> <strong>{todayMood.label}</strong></p>
          <div className="mood-support-tip" style={{marginTop:12, color:'#1976d2', fontSize:'1.08rem'}}>
            <span role="img" aria-label="tip">💡</span> {moodTips[todayMood.label]}
          </div>
          <button className="mood-reset-btn" onClick={handleReset}>Change Mood</button>
        </div>
      )}
      <div className="mood-history">
        <h4 style={{marginTop: 18, marginBottom: 6}}>Your Recent Mood Log:</h4>
        {history.length === 0 ? (
          <p>No moods logged yet.</p>
        ) : (
          <div className="mood-history-row">
            {history.map((m, i) => (
              <span key={i} title={m.label} className="mood-history-emoji">{m.emoji}</span>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

const GratitudeJournal = () => {
  const [entries, setEntries] = useState([]);
  const [input, setInput] = useState("");
  const [showInfo, setShowInfo] = useState(false);

  const handleAdd = e => {
    e.preventDefault();
    // Only allow entries with at least one word (letters) and not just random letters or gibberish
    const trimmed = input.trim();
    // Require at least one word of 2+ letters, and not just a single letter or random chars
    if (!/^([a-zA-Z]{2,}|[a-zA-Z]+[\s,.!?-]+[a-zA-Z]+).*/.test(trimmed)) {
      setInput("");
      return;
    }
    setEntries([trimmed, ...entries]);
    setInput("");
  };

  return (
    <div className="card-area">
      <h3>Gratitude Journal <span role="img" aria-label="gratitude">🌻</span></h3>
      <button
        style={{
          background: '#e3f0fa',
          color: '#1976d2',
          border: '1px solid #b6d6f2',
          borderRadius: 8,
          padding: '8px 16px',
          fontWeight: 600,
          marginBottom: 12,
          cursor: 'pointer',
          fontSize: '1rem',
        }}
        aria-expanded={showInfo}
        aria-controls="gratitude-info"
        onClick={() => setShowInfo(v => !v)}
      >
        {showInfo ? 'Hide Info' : 'Why keep a gratitude journal?'}
      </button>
      {showInfo && (
        <div id="gratitude-info" style={{
          background: '#e3f0fa',
          borderRadius: 8,
          padding: '12px 16px',
          marginBottom: 16,
          color: '#2d3a4a',
          fontSize: '1.05rem',
          textAlign: 'left',
          boxShadow: '0 2px 8px #b6d6f233',
        }}>
          <strong>Gratitude journaling</strong> is a simple but powerful way to boost your mood and mental health. 🌈
          <ul style={{margin: '10px 0 0 18px'}}>
            <li>It helps you notice the good things, even on tough days.</li>
            <li>Writing down what you’re thankful for can make you feel happier and less stressed. 😊</li>
            <li>It’s a great way to remind yourself of your strengths and what matters to you. 💪</li>
            <li>Even small things count—like a smile from a friend, a tasty snack, or a song you love! 🎶</li>
          </ul>
          Try adding something new each day. You might be surprised how much good you can find! 🌟
        </div>
      )}
      <form className="gratitude-form" onSubmit={handleAdd} autoComplete="off">
        <input
          type="text"
          value={input}
          onChange={e => setInput(e.target.value)}
          placeholder="What are you grateful for today?"
          maxLength={120}
        />
        <button type="submit">Add</button>
      </form>
      <ul className="gratitude-list">
        {entries.length === 0 && <li style={{color:'#b6d6f2'}}>No entries yet. Start with one thing you’re grateful for!</li>}
        {entries.map((entry, idx) => (
          <li key={idx}>• {entry}</li>
        ))}
      </ul>
    </div>
  );
};

const BreathingExercise = () => {
  const [phase, setPhase] = useState('breathe-in');
  const [count, setCount] = useState(4);
  const [running, setRunning] = useState(false);
  React.useEffect(() => {
    if (!running) return;
    if (count === 0) {
      if (phase === 'breathe-in') {
        setPhase('hold'); setCount(4);
      } else if (phase === 'hold') {
        setPhase('breathe-out'); setCount(4);
      } else if (phase === 'breathe-out') {
        setPhase('breathe-in'); setCount(4);
      }
      return;
    }
    const timer = setTimeout(() => setCount(count - 1), 1000);
    return () => clearTimeout(timer);
  }, [count, phase, running]);
  const start = () => { setRunning(true); setPhase('breathe-in'); setCount(4); };
  const stop = () => { setRunning(false); setPhase('breathe-in'); setCount(4); };
  let phaseText = '';
  if (phase === 'breathe-in') phaseText = 'Breathe in...';
  if (phase === 'hold') phaseText = 'Hold...';
  if (phase === 'breathe-out') phaseText = 'Breathe out...';

  // Graph animation logic
  // Animate the amplitude of a sine wave based on phase
  const [wavePhase, setWavePhase] = useState(0);
  React.useEffect(() => {
    if (!running) return;
    const anim = setInterval(() => setWavePhase(p => p + 0.08), 30);
    return () => clearInterval(anim);
  }, [running]);
  let amplitude = 18;
  if (phase === 'breathe-in') amplitude = 36;
  if (phase === 'hold') amplitude = 24;
  if (phase === 'breathe-out') amplitude = 8;
  // Generate SVG path for sine wave
  function getSinePath(amp, phaseShift) {
    let d = '';
    for (let x = 0; x <= 200; x += 2) {
      const y = 40 + amp * Math.sin((x / 200) * 2 * Math.PI + phaseShift);
      d += (x === 0 ? 'M' : 'L') + x + ',' + y + ' ';
    }
    return d;
  }

  return (
    <div className="card-area">
      <h3>Breathing Exercise <span role="img" aria-label="breathing">🫁</span></h3>
      <div className="breathing-guide">
        <div className={`breathing-circle ${phase} ${running ? 'running' : ''}`}>{running ? count : 4}</div>
        <div className="breathing-phase">{phaseText}</div>
        <svg width="210" height="80" className="breathing-wave" aria-hidden="true" style={{marginBottom: 8}}>
          <path
            d={getSinePath(amplitude, wavePhase)}
            stroke="#4bb3fd"
            strokeWidth="4"
            fill="none"
            style={{transition: 'stroke 0.3s'}}
          />
        </svg>
        <div className="breathing-controls">
          {!running ? <button onClick={start}>Start</button> : <button onClick={stop}>Stop</button>}
        </div>
      </div>
      <p style={{marginTop:8, color:'#2d7fa5'}}>Try a few rounds to calm your mind and body.</p>
    </div>
  );
};

const SupportSection = ({ feature }) => {
  // If a feature prop is provided, render only that feature (for App.js layout)
  if (feature) {
    switch (feature) {
      case 'virtual-therapist':
        return <VirtualTherapist />;
      case 'mood-tracker':
        return <MoodTracker />;
      case 'gratitude-journal':
        return <GratitudeJournal />;
      case 'breathing-exercise':
        return <BreathingExercise />;
      case 'mental-health-quiz':
        return <MentalHealthQuiz />;
      default:
        return null;
    }
  }

  // Reorder support tools: Virtual Assistant → Breathing Exercise → Quiz → Gratitude Journal → How are you feeling
  return (
    <section id="support" className="support-section">
      <div className="support-feature therapist" id="virtual-therapist" tabIndex="-1">
        <VirtualTherapist />
      </div>
      <div className="support-feature breathing" id="breathing-exercise" tabIndex="-1">
        <BreathingExercise />
      </div>
      <div className="support-feature quiz" id="mental-health-quiz" tabIndex="-1">
        <MentalHealthQuiz />
      </div>
      <div className="support-feature gratitude" id="gratitude-journal" tabIndex="-1">
        <GratitudeJournal />
      </div>
      <div className="support-feature mood" id="mood-tracker" tabIndex="-1">
        <MoodTracker />
      </div>
    </section>
  );
};

export default SupportSection;