const languageOptions = [
  { code: 'en', label: 'English' },
  { code: 'es', label: 'Español' },
  { code: 'zh', label: '中文' },
  { code: 'hi', label: 'हिन्दी' },
  { code: 'ar', label: 'العربية' },
  { code: 'fr', label: 'Français' },
  { code: 'de', label: 'Deutsch' },
  { code: 'it', label: 'Italiano' },
  { code: 'ja', label: '日本語' },
  { code: 'ru', label: 'Русский' },
  { code: 'pt', label: 'Português' },
];

function translateText(text, lang) {
  if (lang === 'en') return text;
  for (const key in translations[lang]) {
    if (text.trim() === key.trim()) return translations[lang][key];
  }
  return text;
}

function App() {
  const [section, setSection] = useState('about');
  const [lang, setLang] = useState('en');
  const [zoom, setZoom] = useState(100);
  const [helpOpen, setHelpOpen] = useState(false);
  const [pendingZoom, setPendingZoom] = useState(100);
  const [feedbackModalOpen, setFeedbackModalOpen] = useState(false);

  // Debounce zoom effect for smoothness
  React.useEffect(() => {
    const handler = setTimeout(() => {
      document.documentElement.style.zoom = `${pendingZoom}%`;
      setZoom(pendingZoom);
    }, 120);
    return () => clearTimeout(handler);
  }, [pendingZoom]);

  // Scroll to feature by id after switching to support section
  const scrollToFeature = (featureId) => {
    setSection('support');
    setHelpOpen(false);
    setTimeout(() => {
      const el = document.getElementById(featureId);
      if (el) {
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        el.focus && el.focus();
      }
    }, 200);
  };

  const renderSection = () => {
    switch (section) {
      case 'support':
        return <SupportSection />;
      case 'resources':
        return <ResourcesSection />;
      case 'contact':
        return <ContactSection />;
      case 'about':
      default:
        return <AboutSection />;
    }
  };

  // Only show the wider feedback section under 'Our Ways We Can Help'
  const feedbackSection = (
    <section className="feedback-section">
      <h2>🌟 Your Feedback Matters</h2>
      <p>How was your experience using this site? Let us know so we can make it even better for teens like you!</p>
      <p style={{color:'#1976d2', fontSize:'0.98rem', marginBottom: '10px'}}><strong>Note:</strong> All feedback will be sent to ryanpstevens08@gmail.com.</p>
      <form className="feedback-form" onSubmit={async e => {
        e.preventDefault();
        const feedback = e.target.elements.feedback.value;
        try {
          await emailjs.send('service_c178wbb', 'template_7nujky6', {
            feedback,
            to_email: 'ryanpstevens08@gmail.com',
          }, '1Eg4vGI_3vjhHuKBB');
          setFeedbackModalOpen(true);
          e.target.reset();
        } catch (err) {
          alert('Sorry, there was a problem sending your feedback.');
        }
      }}>
        <label htmlFor="feedback">Your feedback:</label>
        <textarea id="feedback" name="feedback" rows="3" required placeholder="Share your thoughts..." />
        <button type="submit">Send Feedback</button>
      </form>
    </section>
  );

  return (
    <div className="App">
      <header>
        <h1>{translateText('Teen Mental Health Support', lang)}</h1>
        <p>{translateText('Your feelings matter. This is a safe, caring space to find support and hope. 💙', lang)}</p>
        <img src="data:image/png;base64," />
        <nav aria-label="Main Navigation">
          <ul>
            <li><button onClick={() => setSection('about')} className={section === 'about' ? 'active' : ''} aria-current={section === 'about'}>{translateText('About Mental Health', lang)}</button></li>
            <li><button onClick={() => setSection('support')} className={section === 'support' ? 'active' : ''} aria-current={section === 'support'}>{translateText('Our Ways We Can Help', lang)}</button></li>
            <li><button onClick={() => setSection('resources')} className={section === 'resources' ? 'active' : ''} aria-current={section === 'resources'}>Other Recommended Resources</button></li>
            <li><button onClick={() => setSection('contact')} className={section === 'contact' ? 'active' : ''} aria-current={section === 'contact'}>{translateText('Contact Us', lang)}</button></li>
          </ul>
        </nav>
        <div className="translate-bar">
          <label htmlFor="lang-select">🌐 Translate (Language):</label>
          <select id="lang-select" value={lang} onChange={e => setLang(e.target.value)}>
            {languageOptions.map(opt => (
              <option key={opt.code} value={opt.code}>{opt.label}</option>
            ))}
          </select>
        </div>
      </header>
      <main>
        <div className="accessibility-bar">
          <div className="zoom-controls">
            <label htmlFor="zoom-minus" style={{marginLeft: 16, marginRight: 8}}>Zoom:</label>
            <button
              id="zoom-minus"
              aria-label="Zoom out"
              style={{marginRight: 4, fontSize: '1.2rem', padding: '6px 14px'}}
              onClick={() => setPendingZoom(z => Math.max(90, z - 10))}
              disabled={pendingZoom <= 90}
            >
              –
            </button>
            <span style={{margin: '0 8px', color: '#2d7fa5', fontWeight: 500, minWidth: 38, display: 'inline-block', textAlign: 'center'}}>{pendingZoom}%</span>
            <button
              id="zoom-plus"
              aria-label="Zoom in"
              style={{fontSize: '1.2rem', padding: '6px 14px'}}
              onClick={() => setPendingZoom(z => Math.min(140, z + 10))}
              disabled={pendingZoom >= 140}
            >
              +
            </button>
          </div>            <div className="theme-container">
              <span>Toggle Dark Mode</span>
              <label className="theme-switch">
                <input
                  type="checkbox"
                  onChange={() => document.body.classList.toggle('high-contrast')}
                  aria-label={translateText('Toggle High Contrast (dark mode)', lang)}
                />
                <span className="theme-slider"></span>
              </label>
            </div>
        </div>
        {section === 'support' ? (
          <div className="support-section-spaced">
            <div className="support-feature-area" id="virtual-therapist">
              <SupportSection feature="virtual-therapist" />
            </div>
            <div className="support-feature-row">
              <div className="support-feature-area half-width" id="breathing-exercise">
                <SupportSection feature="breathing-exercise" />
              </div>
              <div className="support-feature-area half-width" id="mental-health-quiz">
                <SupportSection feature="mental-health-quiz" />
              </div>
            </div>
            <div className="support-feature-area" id="gratitude-journal">
              <SupportSection feature="gratitude-journal" />
            </div>
            <div className="support-feature-area" id="mood-tracker">
              <SupportSection feature="mood-tracker" />
            </div>
          </div>
        ) : renderSection()}
        {section !== 'contact' && feedbackSection}
        {/* Floating Help Button */}
        <button
          className="floating-help-btn"
          aria-label="Open help and quick support"
          onClick={() => setHelpOpen(true)}
        >
          <span aria-hidden="true" style={{fontSize: '1.7rem'}}>❓</span>
        </button>
        {/* Help Modal */}
        {helpOpen && (
          <div className="help-modal-overlay" tabIndex={-1} aria-modal="true" role="dialog" onClick={() => setHelpOpen(false)}>
            <div className="help-modal" onClick={e => e.stopPropagation()}>
              <button className="help-modal-close" aria-label="Close help" onClick={() => setHelpOpen(false)}>&times;</button>
              <h2 style={{color:'#2d7fa5', marginTop:0}}>Need Help or Quick Support?</h2>
              <ul className="help-modal-list">
                <li><strong>In crisis?</strong> <a href="https://kidshelpline.com.au/" target="_blank" rel="noopener noreferrer">Kids Helpline 1800 55 1800</a> | <a href="https://www.lifeline.org.au/" target="_blank" rel="noopener noreferrer">Lifeline 13 11 14</a></li>
                <li><strong>Explore site features:</strong> Try the
                  <a href="#virtual-therapist" className="help-feature-link" onClick={e => {e.preventDefault(); scrollToFeature('virtual-therapist');}}> Virtual Therapist</a>,
                  <a href="#mood-tracker" className="help-feature-link" onClick={e => {e.preventDefault(); scrollToFeature('mood-tracker');}}> Mood Tracker</a>,
                  <a href="#gratitude-journal" className="help-feature-link" onClick={e => {e.preventDefault(); scrollToFeature('gratitude-journal');}}> Gratitude Journal</a>,
                  <a href="#breathing-exercise" className="help-feature-link" onClick={e => {e.preventDefault(); scrollToFeature('breathing-exercise');}}> Breathing Exercise</a>, and
                  <a href="#mental-health-quiz" className="help-feature-link" onClick={e => {e.preventDefault(); scrollToFeature('mental-health-quiz');}}> Self-Check Quiz</a>
                  under <b>Our Ways We Can Help</b>.
                </li>
                <li><strong>Accessibility tips:</strong> Use the <b>Zoom</b> slider and <b>High Contrast</b> button at the top of every page. Translate the site using the language bar above.</li>
                <li><strong>Feedback:</strong> Scroll down to share your thoughts and help us improve!</li>
              </ul>
              <p style={{marginTop:18, color:'#2d7fa5', fontSize:'1.05rem'}}>You are not alone. Support is always just a click away.</p>
            </div>
          </div>
        )}
        {feedbackModalOpen && (
        <div className="feedback-modal-overlay" onClick={() => setFeedbackModalOpen(false)}>
          <div className="feedback-modal" onClick={e => e.stopPropagation()}>
            <h3>Thank You! 💙</h3>
            <p>Your feedback helps us make this space better for everyone. We truly appreciate you taking the time to share your thoughts.</p>
            <button onClick={() => setFeedbackModalOpen(false)}>Close</button>
          </div>
        </div>
      )}
      </main>
      <footer>
        <p>&copy; 2025 Ryan Stevens. All rights reserved.</p>
      </footer>
    </div>
  );
}

export default App;