import React, { useState } from 'react';
import emailjs from 'emailjs-com';

const ContactSection = () => {
    const [form, setForm] = useState({ name: '', email: '', message: '' });
    const [submitted, setSubmitted] = useState(false);

    const handleChange = (e) => {
        setForm({ ...form, [e.target.name]: e.target.value });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        // TODO: Replace YOUR_SERVICE_ID, YOUR_TEMPLATE_ID, YOUR_USER_ID with your EmailJS credentials
        try {
            await emailjs.send('YOUR_SERVICE_ID', 'YOUR_TEMPLATE_ID', {
                name: form.name,
                email: form.email,
                message: form.message,
                to_email: 'ryan.stevens11@education.nsw.gov.au',
            }, 'YOUR_USER_ID');
            setSubmitted(true);
        } catch (err) {
            alert('Sorry, there was a problem sending your message.');
        }
    };

    return (
        <section id="contact" className="contact-section card-area">
            <h2>Contact Support</h2>
            <p style={{color:'#1976d2', fontSize:'0.98rem', marginBottom: '10px'}}><strong>Note:</strong> All messages will be sent to ryanpstevens08@gmail.com.</p>
            <form className="ticket-form" onSubmit={handleSubmit}>
                <label>
                    Name (optional):
                    <input type="text" name="name" value={form.name} onChange={handleChange} />
                </label>
                <label>
                    Email (optional):
                    <input type="email" name="email" value={form.email} onChange={handleChange} />
                </label>
                <label>
                    How can we help you?
                    <textarea name="message" value={form.message} onChange={handleChange} required rows={5} />
                </label>
                <button type="submit">Submit Ticket</button>
            </form>
            {submitted && (
                <div className="ticket-success">
                    <h3>Support Ticket Submitted</h3>
                    <p>Thank you, {form.name || 'Friend'}! Your message has been received. Our team will reach out to you soon.</p>
                </div>
            )}
        </section>
    );
};

export default ContactSection;